import type { FoundationLesson, FoundationPage, LearningDiagram } from "./foundation-types";

function diagram(kind: LearningDiagram["kind"], title: string, nodes: [string, string][], caption: string): LearningDiagram {
  return { kind, title, nodes: nodes.map(([title, text]) => ({ title, text })), caption };
}

function page(title: string, body: string, paragraphs: string[], map: LearningDiagram,
  example: [string, string, string, string], reflection: [string, string], takeaway: string, prompt?: string): FoundationPage {
  return { title, body, prompt, reading: { paragraphs, diagram: map,
    example: { title: example[0], situation: example[1], response: example[2], commentary: example[3] },
    reflection: { question: reflection[0], answer: reflection[1] }, takeaway } };
}

